        t=self.cur(); exp = msg or f"expected '{typ}'"
        self.errors.append((t.line,t.col,f"unexpected '{t.text or 'EOF'}', {exp}")); return t
    def skip_seps(self):
        while self.at('NEWLINE'): self.i+=1
