            if not self.at('NEWLINE','EOF','end','else'): expr=self.expression()
            return Return(expr,tok)
        if self.match('if'):
            tok=self.prev(); cond=self.expression(); self.expect('then')
            then=self.block_until({'else','end'})
            els=[]
            if self.match('else'): els=self.block_until({'end'})
            self.expect('end')
            return IfStmt(cond,then,els,tok)
        if self.match('while'):
            tok=self.prev(); cond=self.expression(); self.expect('do')
            body=self.block_until({'end'}); self.expect('end'); return While(cond,body,tok)
        if self.match('for'):
            tok=self.prev(); name=self.expect('IDENT','expected identifier'); self.expect('in'); it=self.expression(); self.expect('do')
            body=self.block_until({'end'}); self.expect('end'); return For(name.text,it,body,tok)
