        if self.at('}'): self.i+=1
        return CmdBlock(raw,capture,async_,tok)

# ---------- Static analysis ----------
class StaticChecker:
    def __init__(self, filename): self.filename=filename; self.errors=[]
    def error(self,tok,msg): self.errors.append((tok.line,tok.col,msg))
    def check(self, prog):
        self.scope_stack=[{'std'}]
        self.in_function=0
        self.block(prog.body, new_scope=False)
        return self.errors
    def defined(self,name): return any(name in s for s in reversed(self.scope_stack))
    def declare(self,name,tok):
        if name in self.scope_stack[-1]: self.error(tok, f"duplicate variable '{name}'")
        self.scope_stack[-1].add(name)
    def block(self, body, new_scope=True):
        if new_scope: self.scope_stack.append(set())
        for st in body: self.stmt(st)
        if new_scope: self.scope_stack.pop()
    def stmt(self, st):
        if isinstance(st,Let):
            self.declare(st.name,st.tok)
            if st.expr: self.expr(st.expr)
        elif isinstance(st,FunctionDecl):
            self.declare(st.name,st.tok)
            self.scope_stack.append(set(st.params)|{'self'}); self.in_function+=1
            for b in st.body: self.stmt(b)
            self.in_function-=1; self.scope_stack.pop()
        elif isinstance(st,Assign):
            self.lvalue(st.target); self.expr(st.expr)
        elif isinstance(st,ExprStmt): self.expr(st.expr)
        elif isinstance(st,Return):
            if st.expr: self.expr(st.expr)
        elif isinstance(st,IfStmt):
            self.expr(st.cond); self.block(st.then_body); self.block(st.else_body)
        elif isinstance(st,While): self.expr(st.cond); self.block(st.body)
        elif isinstance(st,For):
            self.expr(st.iterable); self.scope_stack.append({st.name}); [self.stmt(x) for x in st.body]; self.scope_stack.pop()
    def lvalue(self,e):
        if isinstance(e,Var):
            if not self.defined(e.name): self.error(e.tok, f"undeclared variable '{e.name}'")
        elif isinstance(e,(Index,Attr)):
            self.expr(e.obj if isinstance(e,Attr) else e.obj)
            if isinstance(e,Index): self.expr(e.index)
        else: self.expr(e)
    def expr(self,e):
        if isinstance(e,Var):
            if e.name=='self' and not self.in_function: self.error(e.tok,"self keyword outside function")
            elif e.name!='self' and not self.defined(e.name): self.error(e.tok, f"undeclared variable '{e.name}'")
        elif isinstance(e,(Literal,)): return
        elif isinstance(e,Unary): self.expr(e.expr)
        elif isinstance(e,Binary): self.expr(e.left); self.expr(e.right)
        elif isinstance(e,IfExpr): self.expr(e.cond); self.block(e.then_body); self.block(e.else_body)
        elif isinstance(e,ArrayLit): [self.expr(x) for x in e.items]
        elif isinstance(e,DictLit): [self.expr(v) for k,v in e.pairs]
        elif isinstance(e,FuncLit):
            self.scope_stack.append(set(e.params)|{'self'}); self.in_function+=1
            [self.stmt(x) for x in e.body]
            self.in_function-=1; self.scope_stack.pop()
        elif isinstance(e,Call): self.expr(e.callee); [self.expr(a) for a in e.args]
        elif isinstance(e,Index): self.expr(e.obj); self.expr(e.index)
        elif isinstance(e,Attr): self.expr(e.obj)
        elif isinstance(e,CmdBlock): self.check_cmd_vars(e)
    def check_cmd_vars(self, e):
        raw=e.raw
        # $name and ${name}; skip escaped dollars and shell-style $1
        for m in re.finditer(r'(?<!\\)\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))', raw):
            name=m.group(1) or m.group(2)
            # approximate column by offset in raw from command token end
            if not self.defined(name): self.error(Token('', '', None, e.tok.line, e.tok.col + (m.start()+ (2 if e.capture or e.async_ else 1)), e.tok.start,e.tok.end), f"undeclared variable '{name}'")

# ---------- Environment/interpreter ----------
class Env:
    def __init__(self,parent=None): self.parent=parent; self.vars={}
    def define(self,k,v): self.vars[k]=v
    def get(self,k,pos=None):
        if k in self.vars: return self.vars[k]
        if self.parent: return self.parent.get(k,pos)
        raise HushPanic(pos, f"undeclared variable '{k}'")
    def set(self,k,v,pos=None):
        if k in self.vars: self.vars[k]=v; return
        if self.parent: self.parent.set(k,v,pos); return
        raise HushPanic(pos, f"undeclared variable '{k}'")

class Interpreter:
    def __init__(self, filename='<stdin>', argv=None):
        self.filename=filename; self.argv=argv or []; self.env=Env(); self.cwd=os.getcwd(); self.install_std()
    def pos(self,tok): return f"{self.filename} (line {tok.line}, column {tok.col})"
    def panic(self,tok,msg): raise HushPanic(self.pos(tok) if isinstance(tok,Token) else tok, msg)
    def expect_type(self,v,typ,pos):
        if value_type(v)!=typ: self.panic(pos, f"value ({hush_repr(v)}) has unexpected type, expected {typ}")
        return v
    def install_std(self):
        std=HDict()
        def b(name, fn): std.set(name, Builtin('std.'+name, fn))
        b('print', lambda i,a,p: (sys.stdout.write(''.join(to_print(x) for x in a)), sys.stdout.flush(), NIL)[2])
        b('println', lambda i,a,p: (sys.stdout.write(''.join(to_print(x) for x in a)+'\n'), sys.stdout.flush(), NIL)[2])
        b('type', lambda i,a,p: value_type(a[0] if a else NIL))
        b('to_string', lambda i,a,p: to_print(a[0] if a else NIL))
        b('len', self.std_len); b('push', self.std_push); b('pop', self.std_pop)
        b('iter', self.std_iter); b('range', self.std_range); b('import', self.std_import); b('export', lambda i,a,p: a[0] if a else NIL)
        b('args', lambda i,a,p: list(i.argv))
        b('env', lambda i,a,p: os.environ.get(str(a[0]), NIL))
        b('cwd', lambda i,a,p: os.getcwd())
        b('cd', lambda i,a,p: (os.chdir(str(a[0])), NIL)[1])
        b('read', lambda i,a,p: sys.stdin.read())
        b('int', self.std_int); b('float', self.std_float); b('bytes', self.std_bytes)
        b('contains', self.std_contains); b('is_empty', self.std_is_empty); b('split', self.std_split); b('trim', lambda i,a,p: str(a[0]).strip())
        b('substr', self.std_substr); b('replace', self.std_replace); b('glob', lambda i,a,p: sorted(globmod.glob(str(a[0]))))
        b('sort', self.std_sort); b('sleep', lambda i,a,p: (time.sleep(float(a[0])), NIL)[1])
        b('exit', lambda i,a,p: sys.exit(int(a[0]) if a else 0))
        b('panic', lambda i,a,p: (_ for _ in ()).throw(HushPanic(i.pos(p), to_print(a[0] if a else NIL))))
        b('assert', self.std_assert); b('randseed', lambda i,a,p: (random.seed(int(a[0])), NIL)[1]); b('rand', lambda i,a,p: random.random()); b('randint', lambda i,a,p: random.randint(int(a[0]), int(a[1])))
        b('has_error', lambda i,a,p: isinstance(a[0], ErrorValue))
        b('catch', self.std_catch); b('error', lambda i,a,p: ErrorValue(to_print(a[0] if a else 'error'), a[1] if len(a)>1 else NIL))
        b('typecheck', lambda i,a,p: a[0] if a else NIL); b('try_typecheck', lambda i,a,p: a[0] if a else NIL); b('bind', self.std_bind)
        b('regex', lambda i,a,p: str(a[0]) if a else '')
        # nested libs
        hx=HDict(); hx.set('encode', Builtin('std.hex.encode', lambda i,a,p: binascii.hexlify(str(a[0]).encode()).decode())); hx.set('decode', Builtin('std.hex.decode', lambda i,a,p: binascii.unhexlify(str(a[0])).decode()))
        b64=HDict(); b64.set('encode', Builtin('std.base64.encode', lambda i,a,p: base64.b64encode(str(a[0]).encode()).decode())); b64.set('decode', Builtin('std.base64.decode', lambda i,a,p: base64.b64decode(str(a[0])).decode()))
        js=HDict(); js.set('encode', Builtin('std.json.encode', self.std_json_encode)); js.set('decode', Builtin('std.json.decode', self.std_json_decode))
        std.set('hex',hx); std.set('base64',b64); std.set('json',js)
        self.env.define('std', std)
    def std_len(self,i,a,p):
        v=a[0]
        if isinstance(v,(str,list)): return len(v)
        if isinstance(v,HDict): return len(v.map)
        i.panic(p, f"value ({hush_repr(v)}) has unexpected type, expected array or string")
    def std_push(self,i,a,p):
        if not isinstance(a[0],list): i.panic(p,"value has unexpected type, expected array")
        a[0].append(a[1] if len(a)>1 else NIL); return NIL
    def std_pop(self,i,a,p):
        if not isinstance(a[0],list): i.panic(p,"value has unexpected type, expected array")
        return a[0].pop() if a[0] else NIL
    def std_iter(self,i,a,p):
        v=a[0]
        if isinstance(v,list): return IterFunc(v)
        if isinstance(v,str): return IterFunc([Char(c) for c in v])
        i.panic(p, f"value ({hush_repr(v)}) has unexpected type, expected array or string")
    def std_range(self,i,a,p): return RangeIter(int(a[0]), int(a[1]), int(a[2] if len(a)>2 else 1))
    def std_import(self,i,a,p):
        path=str(a[0]); base=os.path.dirname(i.filename) if i.filename not in ('<stdin>','') else os.getcwd()
        full=path if os.path.isabs(path) else os.path.normpath(os.path.join(base,path))
        return run_file(full, [], mode='exec', parent_interp=i, imported=True)
    def std_int(self,i,a,p):
        v=a[0]
        if isinstance(v,int): return v
        if isinstance(v,float): return int(v)
        return int(str(v))
    def std_float(self,i,a,p):
        v=a[0]
        if isinstance(v,(int,float)): return float(v)
        return float(str(v))
    def std_bytes(self,i,a,p): return [Char(c) for c in str(a[0])]
    def std_contains(self,i,a,p):
        cont,item=a[0],a[1]
        if isinstance(cont,str):
            if not isinstance(item,Char): i.panic(p, f"value ({hush_repr(item)}) has unexpected type, expected char")
            return item.ch in cont
        if isinstance(cont,list): return item in cont
        if isinstance(cont,HDict): return item in cont.map
        return False
    def std_is_empty(self,i,a,p):
        v=a[0]
        if isinstance(v,(str,list)): return len(v)==0
        if isinstance(v,HDict): return len(v.map)==0
        return False
    def std_split(self,i,a,p): return str(a[0]).split(str(a[1]))
    def std_substr(self,i,a,p):
        s=str(a[0]); start=int(a[1]); ln=int(a[2]) if len(a)>2 and a[2] is not NIL else len(s)-start
        return s[start:start+ln]
    def std_replace(self,i,a,p): return str(a[0]).replace(str(a[1]), str(a[2]))
    def std_sort(self,i,a,p):
        arr=a[0]
        if isinstance(arr,list): arr.sort(key=lambda x: to_print(x)); return arr
        return NIL
    def std_assert(self,i,a,p):
        if not (isinstance(a[0],bool) and a[0]): i.panic(p, to_print(a[1]) if len(a)>1 else 'assertion failed')
        return NIL
    def std_catch(self,i,a,p):
        # accepts an error and fallback/function; minimal behavior
        return a[1] if len(a)>1 and isinstance(a[0],ErrorValue) else (a[0] if a else NIL)
    def std_bind(self,i,a,p): return a[0] if a else NIL
    def py_to_hush(self,x):
        if x is None: return NIL
        if isinstance(x,bool): return x
        if isinstance(x,int): return x
        if isinstance(x,float): return x
        if isinstance(x,str): return x
        if isinstance(x,list): return [self.py_to_hush(v) for v in x]
        if isinstance(x,dict): return HDict([(k,self.py_to_hush(v)) for k,v in x.items()])
        return NIL
    def hush_to_py(self,x):
        if x is NIL: return None
        if isinstance(x,Char): return x.ch
        if isinstance(x,(bool,int,float,str)): return x
        if isinstance(x,list): return [self.hush_to_py(v) for v in x]
        if isinstance(x,HDict): return {str(k): self.hush_to_py(v) for k,v in x.map.items()}
        return to_print(x)
    def std_json_encode(self,i,a,p): return json.dumps(self.hush_to_py(a[0]), indent=2)
    def std_json_decode(self,i,a,p): return self.py_to_hush(json.loads(str(a[0])))
    def eval_program(self,prog): return self.eval_block(prog.body,self.env)
    def eval_block(self,body,env):
        old=self.env; self.env=env; res=NIL
        try:
            for st in body: res=self.eval_stmt(st)
            return res
        finally: self.env=old
    def eval_stmt(self,st):
        if isinstance(st,Let):
            v=self.eval_expr(st.expr) if st.expr else NIL; self.env.define(st.name,v); return v
        if isinstance(st,FunctionDecl):
            f=UserFunction(st.params,st.body,self.env,st.tok,st.name); self.env.define(st.name,f); return f
        if isinstance(st,Assign):
            v=self.eval_expr(st.expr); self.assign(st.target,v); return v
        if isinstance(st,ExprStmt): return self.eval_expr(st.expr)
        if isinstance(st,Return): raise ReturnSignal(self.eval_expr(st.expr) if st.expr else NIL)
        if isinstance(st,IfStmt):
            c=self.eval_expr(st.cond); self.require_bool(c,st.tok)
            return self.eval_block(st.then_body if c else st.else_body, Env(self.env))
        if isinstance(st,While):
            res=NIL
            while True:
                c=self.eval_expr(st.cond); self.require_bool(c,st.tok)
                if not c: break
                res=self.eval_block(st.body, Env(self.env))
            return res
        if isinstance(st,For):
            it=self.eval_expr(st.iterable)
            if not callable_value(it): self.panic(st.tok, f"value ({hush_repr(it)}) has unexpected type, expected function")
            res=NIL
            while True:
                item=call_value(it,self,[],st.tok)
                if not isinstance(item,HDict): self.panic(st.tok,"iterator returned invalid value")
                done=item.get('finished',st.tok)
                if done: break
                env=Env(self.env); env.define(st.name,item.get('value',st.tok))
                res=self.eval_block(st.body,env)
            return res
    def require_bool(self,c,tok):
        if not isinstance(c,bool): self.panic(tok, f"condition ({hush_repr(c)}) is not a boolean")
    def eval_expr(self,e):
        if e is None: return NIL
        if isinstance(e,Literal): return e.value
        if isinstance(e,Var): return self.env.get(e.name,e.tok)
        if isinstance(e,Unary):
            v=self.eval_expr(e.expr)
            if e.op=='-':
                if isinstance(v,int) and not isinstance(v,bool): return -v
                if isinstance(v,float): return -v
                self.panic(e.tok, f"value ({hush_repr(v)}) has unexpected type, expected int or float")
            if e.op=='not':
                if not isinstance(v,bool): self.panic(e.tok, f"value ({hush_repr(v)}) has unexpected type, expected bool")
                return not v
        if isinstance(e,Binary): return self.eval_binary(e)
        if isinstance(e,IfExpr):
            c=self.eval_expr(e.cond); self.require_bool(c,e.tok)
            return self.eval_block(e.then_body if c else e.else_body, Env(self.env))
        if isinstance(e,ArrayLit): return [self.eval_expr(x) for x in e.items]
        if isinstance(e,DictLit): return HDict([(k,self.eval_expr(v)) for k,v in e.pairs])
        if isinstance(e,FuncLit): return UserFunction(e.params,e.body,self.env,e.tok)
        if isinstance(e,Index): return self.index(self.eval_expr(e.obj), self.eval_expr(e.index), e.tok)
        if isinstance(e,Attr): return self.index(self.eval_expr(e.obj), e.name, e.tok)
        if isinstance(e,Call):
            self_obj=None
            if isinstance(e.callee,Attr):
                self_obj=self.eval_expr(e.callee.obj); callee=self.index(self_obj,e.callee.name,e.callee.tok)
            else:
                callee=self.eval_expr(e.callee)
            args=[self.eval_expr(a) for a in e.args]
            if not callable_value(callee): self.panic(e.tok, f"value ({hush_repr(callee)}) has unexpected type, expected function")
            return call_value(callee,self,args,e.tok,self_obj)
        if isinstance(e,CmdBlock): return self.exec_command(e)
    def eval_binary(self,e):
        if e.op=='and':
            l=self.eval_expr(e.left); 
            if not isinstance(l,bool): self.panic(e.tok, f"value ({hush_repr(l)}) has unexpected type, expected bool")
            if not l: return False
            r=self.eval_expr(e.right); 
            if not isinstance(r,bool): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected bool")
            return r
        if e.op=='or':
            l=self.eval_expr(e.left)
            if not isinstance(l,bool): self.panic(e.tok, f"value ({hush_repr(l)}) has unexpected type, expected bool")
            if l: return True
            r=self.eval_expr(e.right)
            if not isinstance(r,bool): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected bool")
            return r
        l=self.eval_expr(e.left); r=self.eval_expr(e.right)
        if e.op in ('+','-','*','/','%'):
            if isinstance(l,int) and not isinstance(l,bool):
                if not (isinstance(r,int) and not isinstance(r,bool)): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected int")
                return {'+':l+r,'-':l-r,'*':l*r,'/': int(l/r),'%': l%r}[e.op]
            if isinstance(l,float):
                if not isinstance(r,float): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected float")
                return {'+':l+r,'-':l-r,'*':l*r,'/': l/r,'%': l%r}[e.op]
            self.panic(e.tok, f"value ({hush_repr(l)}) has unexpected type, expected int or float")
        if e.op=='++':
            if not isinstance(l,str): self.panic(e.tok, f"value ({hush_repr(l)}) has unexpected type, expected string")
            if not isinstance(r,str): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected string")
            return l+r
        if e.op in ('==','!='):
            eq=hush_eq(l,r); return eq if e.op=='==' else not eq
        if e.op in ('<','<=','>','>='):
            if isinstance(l,int) and not isinstance(l,bool):
                if not (isinstance(r,int) and not isinstance(r,bool)): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected int")
            elif isinstance(l,float):
                if not isinstance(r,float): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected float")
            elif isinstance(l,str):
                if not isinstance(r,str): self.panic(e.tok, f"value ({hush_repr(r)}) has unexpected type, expected string")
            else: self.panic(e.tok, f"value ({hush_repr(l)}) has unexpected type, expected int, float or string")
            return {'<':l<r,'<=':l<=r,'>':l>r,'>=':l>=r}[e.op]
    def index(self,obj,idx,tok):
        if isinstance(obj,list):
            if not isinstance(idx,int): self.panic(tok, f"value ({hush_repr(idx)}) has unexpected type, expected int")
            if idx<0 or idx>=len(obj): self.panic(tok, f"index ({idx}) out of bounds")
            return obj[idx]
        if isinstance(obj,str):
            if not isinstance(idx,int): self.panic(tok, f"value ({hush_repr(idx)}) has unexpected type, expected int")
            if idx<0 or idx>=len(obj): self.panic(tok, f"index ({idx}) out of bounds")
            return Char(obj[idx])
        if isinstance(obj,HDict): return obj.get(idx,tok)
        if isinstance(obj,AsyncCommand) and idx=='join':
            return Builtin('async.join', lambda i,a,p: (obj.proc.wait(), NIL)[1])
        self.panic(tok, f"value ({hush_repr(obj)}) has unexpected type, expected array or dict")
    def assign(self,target,v):
        if isinstance(target,Var): self.env.set(target.name,v,target.tok); return
        if isinstance(target,Index):
            obj=self.eval_expr(target.obj); idx=self.eval_expr(target.index)
            if isinstance(obj,list): obj[idx]=v
            elif isinstance(obj,HDict): obj.set(idx,v)
            else: self.panic(target.tok,"invalid assignment target")
            return
        if isinstance(target,Attr):
            obj=self.eval_expr(target.obj)
            if isinstance(obj,HDict): obj.set(target.name,v); return
            self.panic(target.tok,"invalid assignment target")
    def interpolate_cmd(self, raw):
        def repl(m):
            name=m.group(1) or m.group(2)
            val=self.env.get(name, None)
            return shlex.quote(to_print(val))
        s=re.sub(r'(?<!\\)\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))', repl, raw)
        s=s.replace('\\$','$')
        # Hush fd duplication: 1>2 means stdout to stderr, 2>1 means stderr to stdout
        s=re.sub(r'\b([012])>([012])\b', r'\1>&\2', s)
        # simple here-string form: cmd << "text"
        s=re.sub(r'cat\s+<<\s+("[^"]*"|\'[^\']*\'|\S+)', lambda m: 'printf %s\\n '+shlex.quote(m.group(1).strip('"\''))+' | cat', s)
        # forgiving command marker: remove bare ? tokens
        s=re.sub(r'(?<!\S)\?(?!\S)', ' true ', s)
        return s
    def exec_command(self,e):
        script=self.interpolate_cmd(e.raw)
        if e.async_:
            p=subprocess.Popen(script, shell=True, executable='/bin/bash')
            return AsyncCommand(p)
        if e.capture:
            cp=subprocess.run(script, shell=True, executable='/bin/bash', text=True, capture_output=True)
            if cp.returncode!=0:
                data=HDict([('error',HDict([('pos',self.pos(e.tok)),('status',cp.returncode)])),('stdout',cp.stdout),('stderr',cp.stderr)])
                return ErrorValue('command returned non-zero', data)
            return HDict([('stdout',cp.stdout),('stderr',cp.stderr)])
        else:
            subprocess.run(script, shell=True, executable='/bin/bash')
            return NIL

def callable_value(v): return isinstance(v,(UserFunction,Builtin,RangeIter,IterFunc))
def call_value(v,interp,args,pos,self_obj=None): return v(interp,args,pos,self_obj)
def hush_eq(a,b):
    if a is NIL or b is NIL: return a is NIL and b is NIL
    if isinstance(a,Char) and isinstance(b,Char): return a.ch==b.ch
    return a==b

# ---------- pretty AST/program ----------
def ast_expr(e):
    if e is None: return 'nil'
    if isinstance(e,Literal):
        if isinstance(e.value,str): return hush_repr(e.value)
        if isinstance(e.value,Char): return "'"+_escape_string(e.value.ch)+"'"
        return hush_repr(e.value)
    if isinstance(e,Var): return e.name
    if isinstance(e,Unary): return f"{e.op} {ast_expr(e.expr)}" if e.op=='not' else f"-{ast_expr(e.expr)}"
    if isinstance(e,Binary): return f"({ast_expr(e.left)} {e.op} {ast_expr(e.right)})"
    if isinstance(e,Call): return f"{ast_expr(e.callee)}(" + ', '.join(ast_expr(a) for a in e.args) + ")"
    if isinstance(e,Index): return f"{ast_expr(e.obj)}[{ast_expr(e.index)}]"
    if isinstance(e,Attr): return f"{ast_expr(e.obj)}.{e.name}"
    if isinstance(e,ArrayLit): return '[' + ', '.join(ast_expr(x) for x in e.items) + ']'
    if isinstance(e,DictLit): return '@[' + ', '.join(f"{k}: {ast_expr(v)}" for k,v in e.pairs) + ']'
    if isinstance(e,FuncLit): return 'function(' + ', '.join(e.params) + ') ... end'
    if isinstance(e,IfExpr): return 'if ' + ast_expr(e.cond) + ' then ... end'
    if isinstance(e,CmdBlock): return ('${' if e.capture else '&{' if e.async_ else '{') + e.raw.strip() + '}'
    return '?'

def ast_stmt(st,indent=''):
    if isinstance(st,Let): return indent+'let '+st.name+((' = '+ast_expr(st.expr)) if st.expr else '')
    if isinstance(st,FunctionDecl): return indent+'let '+st.name+' = function('+', '.join(st.params)+')\n'+'\n'.join(ast_stmt(x,indent+'\t') for x in st.body)+'\n'+indent+'end'
    if isinstance(st,Assign): return indent+ast_expr(st.target)+' = '+ast_expr(st.expr)
    if isinstance(st,ExprStmt): return indent+ast_expr(st.expr)
    if isinstance(st,Return): return indent+'return '+(ast_expr(st.expr) if st.expr else '')
    if isinstance(st,IfStmt): return indent+'if '+ast_expr(st.cond)+' then\n'+'\n'.join(ast_stmt(x,indent+'\t') for x in st.then_body)+('\n'+indent+'else\n'+'\n'.join(ast_stmt(x,indent+'\t') for x in st.else_body) if st.else_body else '')+'\n'+indent+'end'
    if isinstance(st,While): return indent+'while '+ast_expr(st.cond)+' do\n'+'\n'.join(ast_stmt(x,indent+'\t') for x in st.body)+'\n'+indent+'end'
    if isinstance(st,For): return indent+'for '+st.name+' in '+ast_expr(st.iterable)+' do\n'+'\n'.join(ast_stmt(x,indent+'\t') for x in st.body)+'\n'+indent+'end'
    return indent+'?'

# ---------- Running/CLI ----------
def format_errors(filename, errs):
    for line,col,msg in errs:
        sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")

def parse_source(text,filename):
    lx=Lexer(text,filename); toks=lx.lex(); parser=Parser(toks,text,filename); prog=parser.parse()
    return lx,toks,parser,prog

def run_text(text, filename, argv=None, mode='exec', parent_interp=None, imported=False):
    lx,toks,parser,prog=parse_source(text,filename)
    if mode=='lex':
        print('-'*50)
        for t in toks:
            if t.typ in ('EOF','NEWLINE'): continue
            if t.err: print(f"Error: line {t.line}, column {t.col+1} - {t.err}")
            print(f"{filename} (line {t.line}, column {t.col}):\t{t.display}")
        print('-'*50)
    if mode=='ast':
        print('-'*50); print(f"AST for {filename}")
        for st in prog.body: print(ast_stmt(st))
        print('-'*50)
    # collect errors
    errs=[]
    for line,col,msg in lx.errors: errs.append((line,col,msg))
    for line,col,msg in parser.errors: errs.append((line,col,msg))
    checker=StaticChecker(filename); errs += checker.check(prog)
    if mode=='program' and not errs:
        print('-'*50); print(f"Program for {filename}")
        for st in prog.body: print(ast_stmt(st))
        print('-'*50)
    if errs:
        format_errors(filename,errs); return 2 if not imported else NIL
    if mode=='check': return 0 if not imported else NIL
    interp = parent_interp if parent_interp is not None else Interpreter(filename, argv)
    oldfile=interp.filename; interp.filename=filename
    try:
        res=interp.eval_program(prog)
        return res if imported else 0
    except HushPanic as p:
        sys.stderr.write(f"Panic in {p.pos}: {p.msg}\n")
        return NIL if imported else 127
    finally:
        interp.filename=oldfile

def run_file(path, argv=None, mode='exec', parent_interp=None, imported=False):
    with open(path,'r',encoding='utf-8') as f: text=f.read()
    return run_text(text,path,argv or [],mode,parent_interp,imported)

def main(argv):
    flags=[]; args=[]
    for a in argv[1:]:
        if a in ('-h','--help'): print(HELP); return 0
        if a in ('-V','--version'): print(VERSION); return 0
        if a in ('--lex','--ast','--program','--check'): flags.append(a); continue
        if a.startswith('-') and not args:
            sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [arguments]...\n\nFor more information try --help\n")
            return 1
        args.append(a)
    mode='exec'
    if '--lex' in flags: mode='lex'
    elif '--ast' in flags: mode='ast'
    elif '--program' in flags: mode='program'
    elif '--check' in flags: mode='check'
    if args:
        return run_file(args[0], args[1:], mode)
    else:
        text=sys.stdin.read()
        if text=='': return 0
        return run_text(text,'<stdin>',[],mode)
if __name__=='__main__': sys.exit(main(sys.argv))
