#!/usr/bin/env python3
import sys, os, re, subprocess, shlex, glob as globmod, json, base64, binascii, random, time
from dataclasses import dataclass
from collections import OrderedDict

VERSION = "Hush 0.1.4"
HELP = """Hush 0.1.4
gahag <gabriel.s.b@live.com>
Hush is a unix shell scripting language based on the Lua programming language

USAGE:
    executable [FLAGS] [arguments]...

FLAGS:
