    -V, --version    Prints version information

ARGS:
    <arguments>...    Script and/or arguments"""

class HushPanic(Exception):
    def __init__(self, pos, msg):
        self.pos=pos; self.msg=msg
        super().__init__(msg)

class ReturnSignal(Exception):
    def __init__(self, value): self.value=value

class NilType:
    def __repr__(self): return 'nil'
NIL = NilType()

class Char:
    def __init__(self, ch): self.ch=ch
    def __eq__(self,o): return isinstance(o,Char) and self.ch==o.ch
    def __hash__(self): return hash(('char',self.ch))

class ErrorValue:
    def __init__(self, message, data=None): self.message=message; self.data=data if data is not None else NIL

class Builtin:
    def __init__(self, name, func): self.name=name; self.func=func
    def __call__(self, interp, args, pos=None, self_obj=None): return self.func(interp, args, pos)

class UserFunction:
    def __init__(self, params, body, closure, pos=None, name=None):
        self.params=params; self.body=body; self.closure=closure; self.pos=pos; self.name=name
    def __call__(self, interp, args, pos=None, self_obj=None):
        env=Env(self.closure)
        if self_obj is not None: env.define('self', self_obj)
        for i,p in enumerate(self.params): env.define(p, args[i] if i < len(args) else NIL)
        try:
            return interp.eval_block(self.body, env)
        except ReturnSignal as r:
            return r.value

class AsyncCommand:
    def __init__(self, proc): self.proc=proc

def value_type(v):
    if v is NIL: return 'nil'
    if isinstance(v, bool): return 'bool'
    if isinstance(v, int) and not isinstance(v,bool): return 'int'
    if isinstance(v, float): return 'float'
    if isinstance(v, str): return 'string'
    if isinstance(v, Char): return 'char'
    if isinstance(v, list): return 'array'
    if isinstance(v, HDict): return 'dict'
    if isinstance(v, (UserFunction, Builtin)): return 'function'
    if isinstance(v, ErrorValue): return 'error'
    if isinstance(v, RangeIter): return 'function'
    if isinstance(v, IterFunc): return 'function'
    if isinstance(v, AsyncCommand): return 'dict'
    return 'unknown'

class HDict:
    def __init__(self, pairs=None):
        self.map=OrderedDict()
        if pairs:
            for k,v in pairs: self.map[k]=v
    def get(self,k,pos=None):
        if k in self.map: return self.map[k]
        raise HushPanic(pos, f"index ({hush_repr(k)}) out of bounds")
    def set(self,k,v): self.map[k]=v
    def contains(self,k): return k in self.map

class RangeIter:
    def __init__(self,start,end,step): self.cur=start; self.end=end; self.step=step
    def __call__(self, interp, args, pos=None, self_obj=None):
        done = self.cur >= self.end if self.step > 0 else self.cur <= self.end
        if done: return HDict([('finished', True)])
        v=self.cur; self.cur += self.step
        return HDict([('finished', False), ('value', v)])

class IterFunc:
    def __init__(self, seq): self.seq=seq; self.i=0
    def __call__(self, interp, args, pos=None, self_obj=None):
        if self.i >= len(self.seq): return HDict([('finished', True)])
        v=self.seq[self.i]; self.i+=1
        return HDict([('finished', False), ('value', v)])

# ---------- formatting ----------
def _escape_string(s):
    return s.replace('\\','\\\\').replace('\n','\\n').replace('\0','\\0').replace('"','\\"')

def hush_repr(v):
    if v is NIL: return 'nil'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float):
        # Rust's default float formatting is close: integral floats have no trailing .0
        if v == float('inf'): return 'inf'
        if v == float('-inf'): return '-inf'
        if v != v: return 'NaN'
        s=("%.15g" % v)
        return s
    if isinstance(v,str): return '"'+_escape_string(v)+'"'
    if isinstance(v,Char): return v.ch
    if isinstance(v,list): return '[ ' + ', '.join(hush_repr(x) for x in v) + ' ]'
    if isinstance(v,HDict):
        parts=[]
        for k in reversed(list(v.map.keys())):
            parts.append(hush_repr(str(k)) + ': ' + hush_repr(v.map[k]))
        return '@[ ' + ', '.join(parts) + ' ]'
    if isinstance(v,ErrorValue): return f'error: {hush_repr(v.message)} ({hush_repr(v.data)})'
    if isinstance(v,Builtin): return v.name + '<impl>'
    if isinstance(v,RangeIter): return 'std.range<impl>'
    if isinstance(v,IterFunc): return 'std.iter<impl>'
    if isinstance(v,UserFunction): return 'function<impl>'
    if isinstance(v,AsyncCommand): return '@[ "join": async.join<impl> ]'
    return str(v)

def to_print(v):
    if isinstance(v,str): return v
    if isinstance(v,Char): return v.ch
    return hush_repr(v)

# ---------- tokens ----------
@dataclass
class Token:
    typ: str; text: str; value: object; line: int; col: int; start: int; end: int; err: str=None; display: str=None

SYMS = ['==','!=','<=','>=','++','<<','>>','${','&{','->','+','-','*','/','%','<','>','=','(',')','[',']','@',',',':','.',';','{','}']
KEYWORDS = {'let','function','end','if','then','else','while','do','for','in','return','true','false','nil','and','or','not','self'}

class Lexer:
    def __init__(self, text, filename): self.text=text; self.filename=filename; self.i=0; self.line=1; self.col=0; self.tokens=[]; self.errors=[]
    def peek(self,n=0): return self.text[self.i+n] if self.i+n < len(self.text) else ''
    def adv(self):
        ch=self.text[self.i]; self.i+=1
        if ch=='\n': self.line+=1; self.col=0
        else: self.col+=1
        return ch
    def add(self,typ,text,val,line,col,start,end,err=None,display=None): self.tokens.append(Token(typ,text,val,line,col,start,end,err,display))
    def posfmt(self,line,col): return f"line {line}, column {col}"
    def lex(self):
        while self.i < len(self.text):
            ch=self.peek(); start=self.i; line=self.line; col=self.col
            if ch in ' \t\r': self.adv(); continue
            if ch=='\n': self.adv(); self.add('NEWLINE','\n',None,line,col,start,self.i,display='\n'); continue
            if ch=='#':
                while self.i < len(self.text) and self.peek()!='\n': self.adv()
                continue
            if ch.isalpha() or ch=='_':
                s=''
                while self.i < len(self.text) and (self.peek().isalnum() or self.peek()=='_'):
                    s+=self.adv()
                typ = s if s in KEYWORDS else 'IDENT'
                self.add(typ,s,s,line,col,start,self.i,display=s); continue
            if ch.isdigit():
                s=''
                while self.i < len(self.text) and self.peek().isdigit(): s+=self.adv()
                is_float=False
                if self.peek()=='.' and self.i+1 < len(self.text) and self.text[self.i+1].isdigit():
                    is_float=True; s+=self.adv()
                    while self.i < len(self.text) and self.peek().isdigit(): s+=self.adv()
                if self.peek() in 'eE':
                    is_float=True; s+=self.adv()
                    # original does not accept signed exponents
                    while self.i < len(self.text) and self.peek().isdigit(): s+=self.adv()
                try:
                    val=float(s) if is_float else int(s)
                except Exception:
                    val=0.0 if is_float else 0
                disp = ("%.15g" % val) if is_float else str(val)
                self.add('NUMBER',s,val,line,col,start,self.i,display=disp); continue
            if ch in ('"',"'"):
                quote=self.adv(); raw=quote; val=''; bad=None; badcol=None
                while self.i < len(self.text):
                    c=self.adv(); raw+=c
                    if c==quote: break
                    if c=='\\':
                        if self.i>=len(self.text): break
                        e=self.adv(); raw+=e
                        maps={'n':'\n','0':'\0','"':'"',"'":"'",'\\':'\\','$':'$','t':'\t'}
                        if e in maps: val+=maps[e]
                        else:
                            bad=f"invalid escape sequence '\\{e}'."; badcol=self.col-1; val+='\0'
                    else:
                        val+=c
                if quote=="'":
                    typ='CHAR'
                    # keep first char; parse will report if extra as the original often tokenizes oddly
                    v=Char(val[0] if val else '\0')
                else:
                    typ='STRING'; v=val
                if bad:
                    msg=f"Error: line {line}, column {badcol} - {bad}"
                    self.errors.append((line,badcol,bad))
                disp=raw if not bad else ("'\\0'" if quote=="'" else '"'+_escape_string(val)+'"')
                self.add(typ,raw,v,line,col,start,self.i,err=bad,display=disp); continue
            matched=None
            for sym in SYMS:
                if self.text.startswith(sym,self.i): matched=sym; break
            if matched:
                for _ in matched: self.adv()
                self.add(matched,matched,matched,line,col,start,self.i,display=matched); continue
            self.adv(); self.add('INVALID',ch,ch,line,col,start,self.i,display=ch)
        self.add('EOF','',None,self.line,self.col,self.i,self.i,display='')
        return self.tokens

