class While(Node): cond:object; body:list; tok:Token
@dataclass
class For(Node): name:str; iterable:object; body:list; tok:Token
@dataclass
class Literal(Node): value:object; tok:Token
@dataclass
class Var(Node): name:str; tok:Token
@dataclass
class Unary(Node): op:str; expr:object; tok:Token
@dataclass
class Binary(Node): left:object; op:str; right:object; tok:Token
@dataclass
